    # recompute anchor cells: use min col then min row of each object's cells
    def anchor(o):
        ys=[i for i,row in enumerate(o['sh']) for j,v in enumerate(row) if v]
        xs=[j for i,row in enumerate(o['sh']) for j,v in enumerate(row) if v]
        return (min(xs),min(ys))
